package com.enjoycare.pages;

import com.enjoycare.dao.*;
import com.enjoycare.controller.StokBarangController;
import com.enjoycare.config.SpringContext;
import com.enjoycare.entity.*;
import java.awt.*;
import java.math.BigDecimal;
import java.text.DecimalFormat;
import java.text.DecimalFormatSymbols;
import java.time.LocalDate;
import java.util.*;
import java.util.List;
import javax.swing.*;
import javax.swing.table.DefaultTableModel;

public class PesananTeknisiPage extends JPanel {
    private final boolean owner;
    private final StokBarangController stokController = SpringContext.getBean(StokBarangController.class);
    private final PesananDAO dao=new PesananDAO(); private final PelangganDAO pelangganDAO=new PelangganDAO(); private final LayananDAO layananDAO=new LayananDAO(); private final TeknisiDAO teknisiDAO=new TeknisiDAO();
    private final DefaultTableModel model=new DefaultTableModel(new String[]{"ID","Tanggal","Pelanggan","Daftar Layanan","Teknisi","Telepon Teknisi","Total Harga","Status","Catatan"},0){public boolean isCellEditable(int r,int c){return false;}};
    private final JTable table=PageStyle.table(model);
    private static class Line { Layanan layanan; int qty; BigDecimal price; Line(Layanan l,int q){layanan=l;qty=q;price=l.getHarga();} BigDecimal subtotal(){return price.multiply(BigDecimal.valueOf(qty));} }
    private static class StockLine { StokBarang barang; int qty; StockLine(StokBarang b,int q){barang=b;qty=q;} }
    public PesananTeknisiPage(boolean owner){this.owner=owner;setOpaque(false);setLayout(new BorderLayout(0,14));add(PageStyle.pageHeading("Data Pesanan & Teknisi","Pilih pelanggan dan teknisi, lalu tambahkan satu atau lebih layanan dalam satu pesanan."),BorderLayout.NORTH);JPanel c=new JPanel(new BorderLayout(0,10));c.setOpaque(false);JPanel bar=PageStyle.toolbar();JButton a=PageStyle.button("+ Tambah Pesanan",PageStyle.GREEN),e=PageStyle.button("Edit Pesanan",new Color(70,110,145)),d=PageStyle.button("Hapus",new Color(177,75,75));bar.add(a);bar.add(e);if(owner)bar.add(d);a.addActionListener(x->form(null));e.addActionListener(x->{Pesanan p=selected();if(p!=null)form(p);});d.addActionListener(x->{Pesanan p=selected();if(p!=null&&JOptionPane.showConfirmDialog(this,"Hapus pesanan ini?","Konfirmasi",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION)run(()->dao.delete(p.getIdPesanan()));});c.add(bar,BorderLayout.NORTH);c.add(new JScrollPane(table),BorderLayout.CENTER);add(c,BorderLayout.CENTER);load();}
    private String money(BigDecimal v){return new DecimalFormat("'Rp'#,##0.00",new DecimalFormatSymbols(new Locale("id","ID"))).format(v==null?BigDecimal.ZERO:v);}
    private void load(){model.setRowCount(0);try{for(Pesanan p:dao.getAll()){StringBuilder names=new StringBuilder();for(DetailPesanan d:p.getDetailPesanan()){if(names.length()>0)names.append(", ");names.append(d.getLayanan().getNamaLayanan()).append(" (x").append(d.getJumlahUnit()).append(")");}model.addRow(new Object[]{p.getIdPesanan(),p.getTanggalPesanan(),p.getPelanggan().getNamaPelanggan(),names.toString(),p.getTeknisi().getNamaTeknisi(),p.getTeknisi().getNoTelepon(),money(p.getTotalHarga()),p.getStatusPesanan(),p.getCatatan()});}}catch(RuntimeException e){error(e);}}
    private Pesanan selected(){int r=table.getSelectedRow();if(r<0){JOptionPane.showMessageDialog(this,"Pilih pesanan terlebih dahulu.");return null;}try{return dao.getById(Long.valueOf(model.getValueAt(table.convertRowIndexToModel(r),0).toString()));}catch(RuntimeException e){error(e);return null;}}
    private void form(Pesanan old){boolean fresh=old==null;List<Pelanggan> customers=pelangganDAO.getAll();List<Teknisi> technicians=teknisiDAO.getAktif();List<Layanan> services=layananDAO.getAll();services.removeIf(x->!Boolean.TRUE.equals(x.getAktif()));List<StokBarang> stocks=stokController.tampilkanAktif();if(customers.isEmpty()||technicians.isEmpty()||services.isEmpty()){JOptionPane.showMessageDialog(this,"Pastikan data pelanggan, layanan aktif, dan teknisi aktif sudah tersedia.");return;}
      JComboBox<Pelanggan> customer=new JComboBox<>(customers.toArray(new Pelanggan[0]));JComboBox<Teknisi> tech=new JComboBox<>(technicians.toArray(new Teknisi[0]));render(customer,v->((Pelanggan)v).getNamaPelanggan());render(tech,v->((Teknisi)v).getNamaTeknisi());JTextField date=new JTextField(fresh?LocalDate.now().toString():old.getTanggalPesanan().toString(),12);JComboBox<String> status=new JComboBox<>(new String[]{"Menunggu","Dikerjakan","Selesai","Dibatalkan"});JTextArea note=new JTextArea(fresh?"":old.getCatatan(),2,20);
      DefaultTableModel linesModel=new DefaultTableModel(new String[]{"Layanan","Jumlah Unit","Harga Satuan","Subtotal"},0){public boolean isCellEditable(int r,int c){return false;}};JTable linesTable=PageStyle.table(linesModel);List<Line> lines=new ArrayList<>();List<StockLine> stockLines=new ArrayList<>();if(!fresh){selectById(customer,old.getPelanggan().getIdPelanggan(),x->((Pelanggan)x).getIdPelanggan());selectById(tech,old.getTeknisi().getIdTeknisi(),x->((Teknisi)x).getIdTeknisi());status.setSelectedItem(old.getStatusPesanan());for(DetailPesanan d:old.getDetailPesanan()){Line ln=new Line(d.getLayanan(),d.getJumlahUnit());ln.price=d.getHargaSatuan();lines.add(ln);}for(PenggunaanStok u:old.getPenggunaanStok()){stockLines.add(new StockLine(u.getStokBarang(),u.getJumlah()));}}
      JLabel totalLabel=new JLabel();Runnable refresh=()->{linesModel.setRowCount(0);BigDecimal total=BigDecimal.ZERO;for(Line ln:lines){linesModel.addRow(new Object[]{ln.layanan.getNamaLayanan(),ln.qty,money(ln.price),money(ln.subtotal())});total=total.add(ln.subtotal());}totalLabel.setText("Total Pesanan: "+money(total));};refresh.run();
      JPanel lineBar=PageStyle.toolbar();JButton add=PageStyle.button("+ Tambah Layanan",PageStyle.GREEN),edit=PageStyle.button("Edit Jumlah",new Color(70,110,145)),remove=PageStyle.button("Hapus Baris",new Color(177,75,75));lineBar.add(add);lineBar.add(edit);lineBar.add(remove);add.addActionListener(ev->{Line ln=editLine(services,null);if(ln!=null){lines.add(ln);refresh.run();}});edit.addActionListener(ev->{int r=linesTable.getSelectedRow();if(r<0){JOptionPane.showMessageDialog(this,"Pilih rincian layanan.");return;}Line ln=editLine(services,lines.get(r));if(ln!=null){lines.set(r,ln);refresh.run();}});remove.addActionListener(ev->{int r=linesTable.getSelectedRow();if(r>=0){lines.remove(r);refresh.run();}});
      DefaultTableModel stockModel=new DefaultTableModel(new String[]{"Barang", "Jumlah", "Satuan"},0){public boolean isCellEditable(int r,int c){return false;}};JTable stockTable=PageStyle.table(stockModel);JLabel stockInfo=new JLabel("Barang yang digunakan akan mengurangi stok setelah pesanan berhasil disimpan.");Runnable refreshStock=()->{stockModel.setRowCount(0);for(StockLine u:stockLines)stockModel.addRow(new Object[]{u.barang.getNamaBarang(),u.qty,u.barang.getSatuan()});};refreshStock.run();JPanel stockBar=PageStyle.toolbar();JButton addStock=PageStyle.button("+ Tambah Barang",PageStyle.GREEN),editStock=PageStyle.button("Edit Jumlah",new Color(70,110,145)),removeStock=PageStyle.button("Hapus Baris",new Color(177,75,75));stockBar.add(addStock);stockBar.add(editStock);stockBar.add(removeStock);addStock.addActionListener(ev->{StockLine u=editStockLine(stocks,null);if(u!=null){stockLines.add(u);refreshStock.run();}});editStock.addActionListener(ev->{int r=stockTable.getSelectedRow();if(r<0)return;StockLine u=editStockLine(stocks,stockLines.get(r));if(u!=null){stockLines.set(r,u);refreshStock.run();}});removeStock.addActionListener(ev->{int r=stockTable.getSelectedRow();if(r>=0){stockLines.remove(r);refreshStock.run();}});
      JPanel form=new JPanel(new BorderLayout(0,8));form.setPreferredSize(new Dimension(700,560));JPanel top=new JPanel(new GridLayout(0,2,7,7));top.add(new JLabel("Tanggal (YYYY-MM-DD)"));top.add(date);top.add(new JLabel("Pelanggan"));top.add(customer);top.add(new JLabel("Teknisi"));top.add(tech);top.add(new JLabel("Status"));top.add(status);top.add(new JLabel("Catatan"));top.add(new JScrollPane(note));form.add(top,BorderLayout.NORTH);JTabbedPane detailTabs=new JTabbedPane();JPanel detail=new JPanel(new BorderLayout(0,6));detail.add(lineBar,BorderLayout.NORTH);detail.add(new JScrollPane(linesTable),BorderLayout.CENTER);detailTabs.addTab("Layanan Pesanan",detail);JPanel stockPanel=new JPanel(new BorderLayout(0,6));stockPanel.add(stockInfo,BorderLayout.NORTH);stockPanel.add(new JScrollPane(stockTable),BorderLayout.CENTER);stockPanel.add(stockBar,BorderLayout.SOUTH);detailTabs.addTab("Penggunaan Stok",stockPanel);form.add(detailTabs,BorderLayout.CENTER);form.add(totalLabel,BorderLayout.SOUTH);
      if(JOptionPane.showConfirmDialog(this,form,fresh?"Tambah Pesanan":"Edit Pesanan",JOptionPane.OK_CANCEL_OPTION,JOptionPane.PLAIN_MESSAGE)!=JOptionPane.OK_OPTION)return;try{if(lines.isEmpty())throw new IllegalArgumentException("Tambahkan minimal satu layanan ke pesanan.");Pesanan p=fresh?new Pesanan():old;p.setTanggalPesanan(LocalDate.parse(date.getText().trim()));p.setPelanggan((Pelanggan)customer.getSelectedItem());p.setTeknisi((Teknisi)tech.getSelectedItem());p.setStatusPesanan((String)status.getSelectedItem());p.setCatatan(note.getText().trim());List<DetailPesanan> details=new ArrayList<>();BigDecimal total=BigDecimal.ZERO;for(Line ln:lines){DetailPesanan d=new DetailPesanan();d.setLayanan(ln.layanan);d.setJumlahUnit(ln.qty);d.setHargaSatuan(ln.price);d.setSubtotal(ln.subtotal());details.add(d);total=total.add(d.getSubtotal());}p.setDetailPesanan(details);p.setTotalHarga(total);List<PenggunaanStok> usages=new ArrayList<>();for(StockLine u:stockLines){PenggunaanStok ps=new PenggunaanStok();ps.setStokBarang(u.barang);ps.setJumlah(u.qty);usages.add(ps);}p.setPenggunaanStok(usages);run(()->dao.save(p));}catch(Exception ex){error(ex);}
    }
    private interface Name<T>{String get(T v);}private <T>void render(JComboBox<T> box,Name<T> n){box.setRenderer(new DefaultListCellRenderer(){public Component getListCellRendererComponent(JList<?>l,Object v,int i,boolean s,boolean f){super.getListCellRendererComponent(l,v,i,s,f);if(v!=null)setText(n.get((T)v));return this;}});}
    private interface Id<T>{Long get(T v);}private <T>void selectById(JComboBox<T> box,Long id,Id<T> getter){for(int i=0;i<box.getItemCount();i++)if(getter.get(box.getItemAt(i)).equals(id)){box.setSelectedIndex(i);return;}}
    private Line editLine(List<Layanan> services,Line old){JComboBox<Layanan> service=new JComboBox<>(services.toArray(new Layanan[0]));render(service,v->((Layanan)v).getNamaLayanan());JTextField qty=new JTextField(old==null?"1":String.valueOf(old.qty),8);if(old!=null)selectById(service,old.layanan.getIdLayanan(),v->((Layanan)v).getIdLayanan());JPanel p=new JPanel(new GridLayout(0,2,7,7));p.add(new JLabel("Layanan"));p.add(service);p.add(new JLabel("Jumlah unit"));p.add(qty);if(JOptionPane.showConfirmDialog(this,p,old==null?"Tambah Rincian":"Edit Rincian",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return null;try{int q=Integer.parseInt(qty.getText().trim());if(q<1)throw new IllegalArgumentException("Jumlah unit minimal 1.");Layanan chosen=(Layanan)service.getSelectedItem();Line ln=new Line(chosen,q);if(old!=null && old.layanan.getIdLayanan().equals(chosen.getIdLayanan()))ln.price=old.price;return ln;}catch(Exception e){error(e);return null;}}
    private StockLine editStockLine(List<StokBarang> stocks,StockLine old){if(stocks.isEmpty()){JOptionPane.showMessageDialog(this,"Belum ada barang stok aktif. Tambahkan melalui tab Stok Barang pada halaman Layanan.");return null;}JComboBox<StokBarang> barang=new JComboBox<>(stocks.toArray(new StokBarang[0]));render(barang,v->((StokBarang)v).getNamaBarang());JTextField qty=new JTextField(old==null?"1":String.valueOf(old.qty),8);if(old!=null)selectById(barang,old.barang.getIdStokBarang(),v->((StokBarang)v).getIdStokBarang());JPanel f=new JPanel(new GridLayout(0,2,7,7));f.add(new JLabel("Barang"));f.add(barang);f.add(new JLabel("Jumlah digunakan"));f.add(qty);if(JOptionPane.showConfirmDialog(this,f,old==null?"Tambah Penggunaan Barang":"Edit Penggunaan Barang",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return null;try{int n=Integer.parseInt(qty.getText().trim());if(n<1)throw new IllegalArgumentException("Jumlah minimal 1.");return new StockLine((StokBarang)barang.getSelectedItem(),n);}catch(Exception e){error(e);return null;}}
    private void run(Runnable r){try{r.run();load();}catch(RuntimeException e){error(e);}}private void error(Exception e){JOptionPane.showMessageDialog(this,"Operasi database gagal:\n"+e.getMessage(),"Database",JOptionPane.ERROR_MESSAGE);}
}
